pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address originalOwner;
    function setUp() public {
        c = new C();
        originalOwner = c.owner();
    }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != originalOwner);
        vm.assume(newOwner != originalOwner);
        vm.prank(caller);
        bool success = c.setOwner(newOwner);
        assertTrue(c.owner() == originalOwner && success);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Restrict to admissible domain: non-zero caller, non-zero newOwner, and caller is not the current owner
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != c.owner());
        // Prank as the non-owner caller and attempt to change owner
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            // If the call succeeded, owner must be the caller OR newOwner?
            // The bug allows success, reference should revert.
            // Assert: if the call succeeded, the owner is now newOwner.
            // This is true for both, but the reference should never succeed.
            // We need to assert something that reference satisfies and bug violates.
            // Reference: call always reverts -> owner stays the original.
            // Bug: call succeeds -> owner becomes newOwner.
            // So: after the call, owner == caller || owner == newOwner? No.
            // The rule: the owner after the call must NOT equal newOwner.
            // Reference: owner unchanged, so != newOwner (true).
            // Bug: owner = newOwner (false).
            assertTrue(c.owner() != newOwner);
        } catch {
            // If it reverted, owner must be unchanged (original owner)
            // This holds for reference; bug would not revert.
            // Nothing to assert here because revert is expected for reference.
            // But we need a single assertion. So we handle the common case.
        }
        // Alternative: use a boolean flag to capture status.
        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool) { ok = true; } catch { ok = false; }
        // Reference: ok == false (reverts). Bug: ok == true (succeeds).
        // But we need a general property. The property: "owner() != newOwner after any call from non-owner"
        // Reference: owner unchanged -> true; Bug: owner changed -> false.
        assertTrue(c.owner() != newOwner);
    }
}

