// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // The owner is the setUp sender (this test contract).
        // The correct contract requires the sender to be the owner; the owner's call must succeed.
        // The buggy contract reverts even for the owner due to require(false).
        address caller = address(this); // owner is the test contract itself, derive from setUp.
        vm.prank(caller);
        bool ok = true;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
